  if (m.includes("use fast") || m.includes("fast code") || m.includes("quick code")) return "fast";
  if (m.includes("use coding") || m.includes("use coder")) return "coding";
  if (m.includes("superdebug") || m.includes("super debug") || m.includes("deep debug")) return "superdebug";
