// src/gateway/todo-quest-routes.ts
var addQuestSchema = z.object({
  title: z.string().trim().min(1).max(200),
  size: z.enum(["quick", "normal", "epic"]).default("normal")
});
function registerTodoQuestRoutes(app, deps) {
  let store = null;
  const getStore = () => {
    store ??= new TodoQuestStore({ path: deps.storePath });
    return store;
  };
  app.get("/api/todos", (c) => {
    if (!deps.requireAuth(c)) return c.json({ error: "unauthorized" }, 401);
    const s = getStore();
    return c.json({ ...s.list(), stats: s.stats() });
  });
  app.post("/api/todos", async (c) => {
    if (!deps.requireAuth(c)) return c.json({ error: "unauthorized" }, 401);
    let body;
    try {
      body = await c.req.json();
    } catch {
      return c.json({ error: "invalid_json" }, 400);
    }
    const parsed = addQuestSchema.safeParse(body);
    if (!parsed.success) return c.json({ error: "invalid_quest", issues: parsed.error.issues }, 400);
    const quest = getStore().add(parsed.data.title, parsed.data.size);
    return c.json({ quest }, 201);
  });
  app.post("/api/todos/:id/complete", (c) => {
    if (!deps.requireAuth(c)) return c.json({ error: "unauthorized" }, 401);
    const result = getStore().complete(c.req.param("id"));
    if (!result) return c.json({ error: "not_found_or_already_done" }, 404);
    return c.json(result);
  });
  app.post("/api/todos/:id/reopen", (c) => {
    if (!deps.requireAuth(c)) return c.json({ error: "unauthorized" }, 401);
    const s = getStore();
    const quest = s.reopen(c.req.param("id"));
    if (!quest) return c.json({ error: "not_found_or_not_done" }, 404);
    return c.json({ quest, stats: s.stats() });
  });
  app.delete("/api/todos/:id", (c) => {
    if (!deps.requireAuth(c)) return c.json({ error: "unauthorized" }, 401);
    if (!getStore().remove(c.req.param("id"))) return c.json({ error: "not_found" }, 404);
    return c.json({ ok: true });
  });
}

// src/gateway/twilio-signature.ts
import { createHmac as createHmac2, timingSafeEqual as timingSafeEqual3 } from "crypto";
function computeTwilioSignature(authToken, url, params = {}) {
  let data = url;
  const keys = Object.keys(params).sort();
  for (const key of keys) {
    data += key + (params[key] ?? "");
  }
  return createHmac2("sha1", authToken).update(data, "utf8").digest("base64");
}
function validateTwilioSignature(authToken, signature, url, params = {}) {
  if (!authToken || !signature) return false;
  const expected = computeTwilioSignature(authToken, url, params);
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return timingSafeEqual3(a, b);
}
function twilioFormParams(body) {
  const out = {};
  for (const [key, value] of Object.entries(body)) {
    if (typeof value === "string") out[key] = value;
  }
  return out;
}

