			oxygenEl.textContent = String(Math.round(oxygen));
			signalEl.textContent = String(Math.round(signal));
			rescuesEl.textContent = String(rescues);
			podFuelEl.textContent = String(podFuel);
			relayChargeEl.textContent = String(relayCharge);
			comboEl.textContent = "x" + combo;
			riskEl.textContent = oxygen < 20 || signal < 18 ? "high" : oxygen < 42 ? "medium" : "low";
			wheel.style.setProperty("--spin", spin + "deg");
			document.querySelectorAll(".lane").forEach((lane, index) => {
				lane.style.filter = index === selectedLane ? "saturate(1.45) brightness(1.03)" : "saturate(0.86)";
			});
