    const start7 = candles.prepare(
      "SELECT close FROM candles WHERE symbol = ? AND timeframe = ? AND openTime <= ? ORDER BY openTime DESC LIMIT 1"
    ).get(benchSymbol, benchTf, cutoff7);
    const start30 = candles.prepare(
      "SELECT close FROM candles WHERE symbol = ? AND timeframe = ? AND openTime <= ? ORDER BY openTime DESC LIMIT 1"
    ).get(benchSymbol, benchTf, cutoff30);
