    realizedPnl7d: round4(realizedPnl7d),
    realizedPnl30d: round4(realizedPnl30d),
    realizedPnlAllTime: round4(realizedPnlAllTime),
    buyHoldBenchmark7d: round4(bench7),
    buyHoldBenchmark30d: round4(bench30),
    apiCost7d: round4(apiCost7d),
    apiCost30d: round4(apiCost30d),
    computeCost30d: round4(computeCost30d),
    net7d: round4(net7d),
    net30d: round4(net30d),
