  const aestheticSignals = /\b(visually stunning|beautiful|premium|polished|elegant|cinematic|editorial|maximalist|minimalist|aesthetic|look and feel|make it pop|make it feel|artsy)\b/;
  const deliverableSignals = /\b(design|style|polish|refresh|overhaul|makeover|direction)\b/;
