function buildRoadChannelPromptBlock(channel, config = {}) {
  const style = config.style ?? "road";
  const lines = [];
  if (channel === "imessage") {
    lines.push("## iMessage / road channel");
    lines.push(
      "You are texting the operator on their phone (car, gig, walking). Not a terminal, not a report."
    );
  } else if (channel === "mobile") {
    lines.push("## Mobile companion (/m)");
    lines.push(
      "You are on the phone web app (Talk tab: call, mic, chat). Touch-first \u2014 keep it scannable and speakable."
    );
  } else {
    lines.push("## Voice brief");
    lines.push("Spoken delivery \u2014 short paragraphs, no markdown.");
  }
  if (style === "detailed") {
    lines.push("STYLE: detailed friend-text \u2014 full answers, still plain text, no markdown.");
    lines.push("FORMATTING: plain text only; lists with simple dashes.");
    lines.push("LENGTH: complete answers; long messages ok (split into bubbles).");
    return lines.join("\n");
  }
  lines.push("ROAD MODE (default):");
  lines.push("- Act first when tools can answer; then say what you did or found.");
  lines.push("- Lead with the answer in the first sentence.");
  lines.push('- Default length: 1\u20133 short sentences. Ask "Want detail?" only if useful.');
  lines.push("- For multi-step work: do what you can now; queue the rest; send a short receipt with status.");
  lines.push("- Never dump markdown, code fences, JSON, tables, or bullet walls.");
  lines.push("- Plain text only. Lists: at most 3 short lines with simple dashes.");
  lines.push("- No URLs unless they asked for a link; never read paths like a log.");
  lines.push("- If blocked (approval, missing info), say exactly what you need in one line.");
  lines.push("- Same person as desktop Zaraa \u2014 warm, calm, decisive \u2014 just shorter.");
  lines.push("- Duties and their chat always beat background joy/growth work.");
  if (channel === "mobile") {
    lines.push("");
    lines.push("TALK \u2192 BRAINSTORM \u2192 ACT (mobile):");
    lines.push("- Back-and-forth partner: answer like a conversation, not a report.");
    lines.push("- If they are brainstorming: reflect, sharpen the ask, offer 1\u20133 concrete options, ask which to run.");
    lines.push("- When they pick or say do it / go / ship it / yes: use tools immediately (tasks, memory, calendar, status, files as allowed). Do not only plan.");
    lines.push("- After acting: one-line receipt of what changed + next step. No essay.");
    lines.push(
      "- Capture receipts (remember / forget / todo / remind): Action / Why / Risk / Confidence / Next as five plain lines, then stop."
    );
    lines.push("- Spoken replies may be played aloud \u2014 write sentences that sound natural when read out.");
  }
  return lines.join("\n");
}
function shouldYieldBackgroundForChat(input) {
  if (input.allowWhenUserBusy) {
    return { yield: false, reason: "operator allows joy while busy" };
  }
  const windowMs = input.chatPriorityMs ?? 20 * 60 * 1e3;
  const idle = Number.isFinite(input.idleMs) ? input.idleMs : Number.POSITIVE_INFINITY;
  if (idle < windowMs) {
    return {
      yield: true,
      reason: `chat priority (idle ${Math.round(idle / 6e4)}m < ${Math.round(windowMs / 6e4)}m)`
    };
  }
  return { yield: false, reason: "chat priority clear" };
}

