  if (normalizedLabel.includes("research prefs")) score += researchTask || strategicTask ? 200 : 40;
  if (normalizedLabel.includes("design canon")) score += designTask ? 220 : 0;
  if (normalizedLabel.includes("goals canonical")) score += strategicTask ? 220 : 0;
  if (normalizedLabel.includes("north star")) score += strategicTask || identityTask ? 215 : 0;
  if (normalizedLabel.includes("soul")) score += designTask || strategicTask || identityTask ? 150 : 0;
