// src/runtime/to-action-result.ts
function toActionResult(evalResult, action, approvalQueue, confidenceScorer, autoApproveThreshold, trustedGateway, autonomyMode, approvalContext) {
  switch (evalResult.status) {
    case "approved":
      return { status: "approved", result: null };
    case "denied":
      return { status: "denied", reason: evalResult.reason || "Policy denied" };
    case "queued": {
      const securityReview = evalResult.reasonCode?.startsWith("anomaly_") === true || evalResult.reasonCode === "security_cooldown";
      let handsOffHardStop = securityReview;
      if (!securityReview && autonomyMode === "handsOff") {
        const decision = resolveHandsOffQueuedAction(action);
        if (decision.autoApprove) {
          return { status: "approved", result: null };
        }
        handsOffHardStop = true;
      } else if (!securityReview && trustedGateway) {
        return { status: "approved", result: null };
      }
      const desc = action.target ? `${action.type}: ${action.target} \u2014 ${JSON.stringify(action.params ?? {}).slice(0, 200)}` : `${action.type}: ${JSON.stringify(action.params ?? {}).slice(0, 200)}`;
      let confidence;
      if (confidenceScorer) {
        const actionAsRecord = action;
        confidence = confidenceScorer.score(actionAsRecord);
        const threshold = autoApproveThreshold ?? DEFAULT_AUTO_APPROVE_THRESHOLD;
        if (!handsOffHardStop && confidence.score >= threshold) {
          return { status: "approved", result: null };
        }
      }
      const approvalId = approvalQueue ? approvalQueue.add({
        action,
        description: desc,
        confidence: confidence?.score,
        rubricScores: confidence?.rubric,
        autoApproved: false,
        sessionId: approvalContext?.sessionId,
        primarySurface: approvalContext?.primarySurface,
        interactionMode: approvalContext?.interactionMode,
        fallbackEligible: approvalContext?.fallbackEligible,
        fallbackReason: approvalContext?.fallbackReason
      }) : `approval-${Date.now()}`;
      return { status: "queued", approvalId };
    }
  }
}

