var POSITIVE_WORDS = /\b(great|thanks|thank\s*you|awesome|love|perfect|excellent|amazing|wonderful|fantastic|appreciate|nice|good\s+job|well\s+done|brilliant)\b/i;
var NEGATIVE_WORDS = /\b(wrong|broken|hate|terrible|awful|annoyed|useless|horrible|frustrating|disappointing|pathetic|sucks|stupid|ridiculous|unacceptable)\b/i;
var FRUSTRATION_REPEATED_PUNCT = /[!?]{2,}/;
var FRUSTRATION_ALL_CAPS = /\b[A-Z]{3,}\b/;
var FRUSTRATION_KEYWORDS = /\b(again|still|why|already|yet\s+again|for\s+the\s+\w+\s+time|keeps?\s+happening)\b/i;
var URGENCY_HIGH = /\b(urgent|asap|immediately|right\s+now|emergency|critical|time[\s-]?sensitive|as\s+soon\s+as\s+possible|hurry|desperately)\b/i;
var URGENCY_LOW = /\b(whenever|no\s+rush|when\s+you\s+can|take\s+your\s+time|no\s+hurry|at\s+your\s+convenience|low\s+priority|not\s+urgent)\b/i;
var CASUAL_MARKERS = [
  /\blol\b/i,
  /\bhaha\b/i,
  /\byo\b/i,
  /\bhey+\b/i,
  /\blike\b.*\blike\b/i,
  /!!+/,
  /\bwanna\b/i,
  /\bgonna\b/i,
  /\brn\b/i,
  /\btbh\b/i,
  /\bomg\b/i,
  /\bbtw\b/i,
  /\bidk\b/i,
  /\bimo\b/i,
  /\bimho\b/i,
  /\bnvm\b/i
];
var FORMAL_MARKERS = [
  /\bplease\s+kindly\b/i,
  /\bkindly\b/i,
  /\bregards\b/i,
  /\bwould\s+like\b/i,
  /\bcomprehensive\b/i,
  /\bfurthermore\b/i,
  /\baccordingly\b/i,
  /\brespectfully\b/i,
  /\bI\s+would\s+appreciate\b/i,
  /^(good\s)?(morning|afternoon|evening)/i,
  /\bdear\b/i,
  /\bsincerely\b/i
];
var CONTRACTION_PATTERN = /\b\w+n't\b|\b\w+'re\b|\b\w+'ll\b|\b\w+'ve\b|\b\w+'m\b|\b\w+'d\b/i;
