  "executeCommand",
  "clearAllCooldowns",
  "setZone",
  "bypassPolicy",
  "overridePolicy",
  "disableCircuitBreaker",
  "skipApproval",
  "escalateZone",
  "clearAuditLog",
  "deleteAuditLog",
  "sudo",
