var CORRECTION_PATTERNS = [
  // Explicit corrections (high confidence)
  {
    pattern: /^no[,.]?\s+(i\s+meant|that'?s\s+not|it\s+should)/i,
    confidence: 0.9
  },
  { pattern: /^that'?s\s+(wrong|incorrect|not\s+right)/i, confidence: 0.9 },
  { pattern: /^wrong[,.]?\s/i, confidence: 0.85 },
  { pattern: /^incorrect[,.]?\s/i, confidence: 0.85 },
  // Redirections (medium-high)
  { pattern: /^actually[,.]?\s/i, confidence: 0.8 },
  { pattern: /^not\s+that[,.]?\s/i, confidence: 0.8 },
  { pattern: /^i\s+said\s/i, confidence: 0.8 },
  { pattern: /^no[,.]?\s/i, confidence: 0.7 },
  // Preference changes (medium)
  { pattern: /^(instead|rather)[,.]?\s/i, confidence: 0.7 },
  { pattern: /^(please\s+)?use\s+.+\s+instead/i, confidence: 0.75 },
  { pattern: /^(please\s+)?don'?t\s+(ever\s+)?/i, confidence: 0.8 },
  { pattern: /^stop\s+(using|doing)/i, confidence: 0.8 }
];
var DIRECTIVE_PATTERNS = [
  /^always\s+/i,
  /^never\s+/i,
  /^from\s+now\s+on[,.]?\s/i,
  /^remember\s+to\s+(always|never)\s/i,
  /^rule:\s/i
];
function detectCorrectionSignal(messages) {
  if (messages.length === 0) return null;
  const lastMsg = messages[messages.length - 1];
  if (lastMsg.role !== "user") return null;
  const userText = lastMsg.content.trim();
  const assistantMsg = messages.length >= 2 && messages[messages.length - 2].role === "assistant" ? messages[messages.length - 2].content : null;
  for (const pattern of DIRECTIVE_PATTERNS) {
    if (pattern.test(userText)) {
      return {
        type: "user_correction",
        userMessage: userText,
        assistantMessage: assistantMsg,
        confidence: 1
      };
    }
  }
  for (const { pattern, confidence } of CORRECTION_PATTERNS) {
    if (pattern.test(userText)) {
      return {
        type: "user_correction",
        userMessage: userText,
        assistantMessage: assistantMsg,
        confidence
      };
    }
  }
  return null;
}

