  const gatedTypes = gate.gatedTaskTypes ?? ["chat"];
  const typeMatch = gatedTypes.includes(taskType);
  const zoneMatch = gate.gatedZones?.length ? gate.gatedZones.includes(task.zone) : false;
  const patternMatch = gate.gatedPatterns?.length ? gate.gatedPatterns.some((re) => re.test(task.prompt)) : false;
  const shouldGate = typeMatch && (zoneMatch || patternMatch);
  if (!shouldGate) return builtInGateNeeded;
  if (patternMatch) return true;
  const sampleRate = gate.routineSampleRate ?? 1;
  if (sampleRate >= 1) return true;
