      "compare",
      "evaluate",
      "assess",
      "review",
      "design",
      "explain",
      "synthesize",
      "recommend",
      "investigate",
      "optimize",
      "strategy",
      "comprehensive",
      "detailed",
      "multi-step",
      "because",
      "therefore",
      "however",
      "although",
      "implications",
      "trade-off"
