    const forbidden = context.evidenceLedger.forbiddenToolCalls;
    if (forbidden.length === 0) return null;
    const banSources = classifyForbiddenToolMentions(task.prompt);
    const localTradingFamilyBlocked = shouldSuppressLocalTradingToolsForTaskPrompt(task.prompt);
    const annotated = forbidden.map((call) => {
      let source;
      if (banSources.has(call.name)) {
        source = banSources.get(call.name);
      } else if (localTradingFamilyBlocked && /^(?:trade|practice|arb)_/.test(call.name)) {
        source = "local-trading-cue-wildcard";
      } else {
        source = "explicit-prompt-mention";
      }
      const sourceTag = source === "local-trading-cue-wildcard" ? " (local-trading-cue-wildcard)" : "";
      return `${this.describeEvidenceCall(call)}${sourceTag}`;
    });
    const evidenceSummary = annotated.join(", ");
    const error = `Forbidden tool boundary rejected: prompt forbids these tool calls but they were observed: ${evidenceSummary}.`;
    return {
      error,
      metadata: {
        qaStatus: "fail",
        failureClass: "policy",
        cleanupBurden: "low",
        acceptanceOutcome: "rejected",
        lastEvidence: evidenceSummary.slice(0, 500)
      }
    };
