    const result = this.db.prepare("DELETE FROM traces WHERE timestamp < ?").run(cutoff);
    const unknownCutoff = new Date(Date.now() - 864e5).toISOString();
    const unknownResult = this.db.prepare("DELETE FROM traces WHERE model = 'unknown' AND timestamp < ?").run(unknownCutoff);
    return result.changes + unknownResult.changes;
