        model: r.model,
        taskType: r.taskType,
        traceCount: r.traceCount,
        successRate: r.traceCount > 0 ? Math.round(r.successCount / r.traceCount * 1e3) / 1e3 : 0,
        avgLatencyMs: Math.round(r.avgLatencyMs),
