var Rollback = class {
  constructor(journal, writeFn, deleteFn) {
    this.journal = journal;
    this.writeFn = writeFn;
    this.deleteFn = deleteFn;
  }
  journal;
  writeFn;
  deleteFn;
  /**
   * Roll back a single journal entry.
   * - For file.write actions: restores preState content (or deletes if preState is null = new file)
   * - Marks the journal entry as "rolled-back"
   * Returns success/failure.
   */
  async rollbackEntry(entryId) {
    const entry = this.journal.get(entryId);
    if (!entry) {
      return { entryId, target: "", success: false, error: "Entry not found" };
    }
    if (entry.status !== "executed") {
      return {
        entryId,
        target: entry.target,
        success: false,
        error: "Entry already rolled back or denied"
      };
    }
    if (!entry.actionType.startsWith("file.")) {
      return {
        entryId,
        target: entry.target,
        success: false,
        error: "Only file actions can be rolled back"
      };
    }
    try {
      if (entry.preState === null && entry.actionType === "file.write") {
        if (!this.deleteFn) {
          return {
            entryId,
            target: entry.target,
            success: false,
            error: "Cannot rollback new file creation (no delete function)"
          };
        }
        await this.deleteFn(entry.target);
      } else if (typeof entry.preState === "string") {
        await this.writeFn(entry.target, entry.preState);
      }
      this.journal.markRolledBack(entryId);
      return { entryId, target: entry.target, success: true };
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      return {
        entryId,
        target: entry.target,
        success: false,
        error: message
      };
    }
  }
  /**
   * Roll back all actions from a task, in reverse chronological order.
   * Only rolls back entries with status "executed" and actionType starting with "file.".
   * Returns array of results.
   */
  async rollbackTask(taskId) {
    const entries = this.journal.getTaskActions(taskId);
    const fileEntries = entries.filter(
      (e) => e.status === "executed" && e.actionType.startsWith("file.")
    );
    fileEntries.reverse();
    const results = [];
    for (const entry of fileEntries) {
      const result = await this.rollbackEntry(entry.id);
      results.push(result);
    }
    return results;
  }
};

