var KERNEL_LIVENESS_TASK_ID = "kernel:liveness-sentinel";
var KERNEL_LIVENESS_CRON = "0 */6 * * *";
var KERNEL_LIVENESS_CHECK_MS = 6 * 36e5;
var KERNEL_QUIET_LIMIT_MS = 12 * 36e5;
var KERNEL_ALERT_DEBOUNCE_MS = 24 * 36e5;
function newKernelLivenessState(now = Date.now()) {
  return { startedTs: now, lastAlertTs: 0 };
}
function checkKernelLiveness(deps, state) {
  const now = deps.now?.() ?? Date.now();
  const log12 = deps.log ?? (() => {
  });
  const lastEventTs = deps.events.latestTs();
  const quietMs = Math.max(0, now - Math.max(lastEventTs, state.startedTs));
  if (quietMs <= KERNEL_QUIET_LIMIT_MS || now - state.lastAlertTs < KERNEL_ALERT_DEBOUNCE_MS) {
    return { quietMs, lastEventTs, alerted: false };
  }
  state.lastAlertTs = now;
  const quietHours = Math.round(quietMs / 36e5 * 10) / 10;
  void Promise.resolve(
    deps.notify(`Autonomy kernel journal quiet for ${quietHours}h \u2014 the kernel may be dark.`)
  ).catch((err) => log12(`[kernel-liveness] notify failed: ${err instanceof Error ? err.message : String(err)}`));
  try {
    deps.events.append({
      ts: now,
      kind: "kernel.liveness.stall",
      weight: 0,
      payload: { quietHours, lastEventTs }
    });
  } catch (err) {
    log12(`[kernel-liveness] journal append failed: ${err instanceof Error ? err.message : String(err)}`);
  }
  log12(`[kernel-liveness] stall alert \u2014 quiet ${quietHours}h (lastEventTs=${lastEventTs})`);
  return { quietMs, lastEventTs, alerted: true };
}
function marker2() {
  return {
    id: KERNEL_LIVENESS_TASK_ID,
    schedule: KERNEL_LIVENESS_CRON,
    zone: "trusted",
    prompt: "kernel liveness sentinel marker \u2014 deterministic, journal-only",
    notify: "none",
    silent: true,
    enabled: false
    // visible in scheduler config, never executed as an LLM prompt
  };
}
function registerKernelLivenessSentinel(scheduler, deps, config) {
  if (!config.enabled) {
    return { stop() {
    } };
  }
  const log12 = deps.log ?? (() => {
  });
  scheduler.addTask(marker2());
  const state = newKernelLivenessState(deps.now?.() ?? Date.now());
  log12("[kernel-liveness] sentinel armed (6h cadence, 12h quiet threshold)");
  const timer = setInterval(() => {
    try {
      checkKernelLiveness(deps, state);
    } catch (err) {
      log12(`[kernel-liveness] check error: ${err instanceof Error ? err.message : String(err)}`);
    }
  }, config.checkIntervalMs ?? KERNEL_LIVENESS_CHECK_MS);
  timer.unref?.();
  return {
    stop() {
      clearInterval(timer);
    }
  };
}

