// src/scheduler/overnight-protocol.ts
var DEFAULT_CONFIG = {
  enabled: true,
  startHour: 23,
  endHour: 7
};
function normalizeHour(hour) {
  const normalized = hour % 24;
  return normalized < 0 ? normalized + 24 : normalized;
}
function getWindowHours(startHour, endHour) {
  const start = normalizeHour(startHour);
  const end = normalizeHour(endHour);
  if (start === end) {
    return Array.from({ length: 24 }, (_, index) => index);
  }
  const hours = [];
  let current = start;
  while (current !== end) {
    hours.push(current);
    current = normalizeHour(current + 1);
  }
  return hours;
}
function pickWindowHours(windowHours, step, offset = 0) {
  const picked = windowHours.filter((_, index) => index % step === offset);
  return picked.length > 0 ? picked : [windowHours[0]];
}
function buildCron(minute, hours) {
  const uniqueHours = [...new Set(hours.map((hour) => normalizeHour(hour)))].sort((a, b) => a - b);
  return `${minute} ${uniqueHours.join(",")} * * *`;
}
function buildOncePerNightHour(windowHours, position) {
  if (windowHours.length === 0) return 0;
  if (position === "early") return windowHours[Math.min(1, windowHours.length - 1)];
  if (position === "late") return windowHours[Math.max(0, windowHours.length - 2)];
  return windowHours[Math.floor(windowHours.length / 2)];
}
