function registerOvernightProtocol(scheduler, config = DEFAULT_CONFIG) {
  if (!config.enabled) return;
  const windowHours = getWindowHours(config.startHour, config.endHour);
  const everyOtherHourA = pickWindowHours(windowHours, 2, 0);
  const everyOtherHourB = pickWindowHours(windowHours, 2, 1);
  const everyFourthHour = pickWindowHours(windowHours, 4, 1);
  const memoryHour = buildOncePerNightHour(windowHours, "middle");
  const researchHour = buildOncePerNightHour(windowHours, "late");
  const handoffHour = normalizeHour(config.endHour);
  scheduler.addTask({
    id: "overnight:regime-scan",
    schedule: buildCron(5, everyOtherHourA),
    zone: "trusted",
    notify: "none",
    silent: true,
    prompt: regimeScanPrompt()
  });
  scheduler.addTask({
    id: "overnight:queue-repair",
    schedule: buildCron(20, everyOtherHourB),
    zone: "trusted",
    notify: "none",
    silent: true,
    prompt: queueRepairPrompt()
  });
  scheduler.addTask({
    id: "overnight:risk-assessment",
    schedule: buildCron(35, everyFourthHour),
    zone: "trusted",
    notify: "none",
    // Live 2026-07-26: silent:false still wrote silent=0 rows every 4h while
    // prompt asks for a quiet risk watch — lifecycle noise with no operator value.
    // Handoff/research stay non-silent for morning visibility.
    silent: true,
    prompt: riskAssessmentPrompt()
  });
  scheduler.addTask({
    id: "overnight:memory-consolidation",
    schedule: buildCron(10, [memoryHour]),
    zone: "trusted",
    notify: "none",
    silent: true,
    prompt: memoryConsolidationPrompt()
  });
  scheduler.addTask({
    id: "overnight:research",
    schedule: buildCron(45, [researchHour]),
    zone: "trusted",
    notify: "none",
    silent: false,
    prompt: researchPrompt()
  });
  scheduler.addTask({
    id: "overnight:operator-handoff",
    schedule: buildCron(5, [handoffHour]),
    zone: "trusted",
    notify: "none",
    silent: false,
    prompt: operatorHandoffPrompt()
  });
  if (config.affiliateRepoPath?.trim() && config.affiliateTag?.trim()) {
    registerAffiliateContentTask(scheduler, {
      repoPath: config.affiliateRepoPath.trim(),
      affiliateTag: config.affiliateTag.trim()
    });
  }
}
