function rowToEvent(row) {
  return {
    id: row.id,
    ts: row.ts,
    kind: row.kind,
    lane: row.lane,
    ref: row.ref,
    weight: row.weight,
    payload: JSON.parse(row.payload)
  };
}
var KernelEventsStore = class {
  constructor(db) {
    this.db = db;
  }
  db;
  /** Append one event. Returns the new row id. */
  append(e) {
    const result = this.db.prepare(
      `INSERT INTO kernel_events (ts, kind, lane, ref, weight, payload, created_at)
				 VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).run(
      e.ts,
      e.kind,
      e.lane ?? null,
      e.ref ?? null,
      e.weight,
      JSON.stringify(e.payload ?? {}),
      Date.now()
    );
    return Number(result.lastInsertRowid);
  }
  /** Events for one lane, ascending ts. sinceTs is exclusive. */
  forLane(lane2, sinceTs = 0) {
    const rows = this.db.prepare(
      `SELECT id, ts, kind, lane, ref, weight, payload
				 FROM kernel_events WHERE lane = ? AND ts > ? ORDER BY ts ASC, id ASC`
    ).all(lane2, sinceTs);
    return rows.map(rowToEvent);
  }
  /** All events with ts > sinceTs, every lane and kind, ascending. Read-only. */
  since(sinceTs) {
    const rows = this.db.prepare(
      `SELECT id, ts, kind, lane, ref, weight, payload
				 FROM kernel_events WHERE ts > ? ORDER BY ts ASC, id ASC`
    ).all(sinceTs);
    return rows.map(rowToEvent);
  }
  /**
   * Events with ts > sinceTs restricted to the given kinds, ascending.
   * Filtering in SQL uses idx_kernel_events_kind_ts; the caller-side
   * alternative reads the whole journal (38k+ rows and growing) to keep a
   * handful. Empty `kinds` returns [] rather than silently meaning "all".
   */
  sinceKinds(sinceTs, kinds) {
    if (kinds.length === 0) return [];
    const placeholders = kinds.map(() => "?").join(", ");
    const rows = this.db.prepare(
      `SELECT id, ts, kind, lane, ref, weight, payload
				 FROM kernel_events WHERE ts > ? AND kind IN (${placeholders})
				 ORDER BY ts ASC, id ASC`
    ).all(sinceTs, ...kinds);
    return rows.map(rowToEvent);
  }
  /** Max ts in the journal, 0 when empty. */
  latestTs() {
    const row = this.db.prepare("SELECT COALESCE(MAX(ts), 0) AS maxTs FROM kernel_events").get();
    return row.maxTs;
  }
};

