// src/tasks/migrations/001_initial_schema.sql
var initial_schema_default6 = `-- Migration 001: Initial task queue schema
-- Creates the tasks table and dependency DAG table.
--
-- tasks            \u2014 the work queue; each row is one unit of work for Zaraa
-- task_dependencies \u2014 tracks which tasks must complete before others can start

-- UP

CREATE TABLE IF NOT EXISTS tasks (
	id          TEXT    NOT NULL PRIMARY KEY,
	prompt      TEXT    NOT NULL,
	status      TEXT    NOT NULL DEFAULT 'pending',
	zone        TEXT    NOT NULL DEFAULT 'guarded',
	priority    TEXT    NOT NULL DEFAULT 'normal',
	result      TEXT,
	createdAt   TEXT    NOT NULL,
	startedAt   TEXT,
	completedAt TEXT,
	source      TEXT    NOT NULL DEFAULT 'api',
	parentId    TEXT,
	silent      INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_tasks_status    ON tasks(status);
CREATE INDEX IF NOT EXISTS idx_tasks_createdAt ON tasks(createdAt);
CREATE INDEX IF NOT EXISTS idx_tasks_parentId  ON tasks(parentId);

-- task_dependencies records the DAG of "A must finish before B runs"
CREATE TABLE IF NOT EXISTS task_dependencies (
	task_id    TEXT NOT NULL,
	depends_on TEXT NOT NULL,
	PRIMARY KEY (task_id, depends_on),
	FOREIGN KEY (task_id)    REFERENCES tasks(id),
	FOREIGN KEY (depends_on) REFERENCES tasks(id)
);

CREATE INDEX IF NOT EXISTS idx_task_deps_depends_on ON task_dependencies(depends_on);

-- DOWN

DROP INDEX IF EXISTS idx_task_deps_depends_on;
DROP TABLE IF EXISTS task_dependencies;
DROP INDEX IF EXISTS idx_tasks_parentId;
DROP INDEX IF EXISTS idx_tasks_createdAt;
DROP INDEX IF EXISTS idx_tasks_status;
DROP TABLE IF EXISTS tasks;
`;

