// src/tasks/migrations/012_autonomy_obs.sql
var autonomy_obs_default = `-- Migration 012: autonomy observability \u2014 tasks.updated_at + autonomy_state
--
-- Two unrelated-but-bundled schema gaps surfaced by the Phase 3 M report:
--
-- 1. tasks.updated_at (epoch ms) \u2014 the "suppressed older than 7d" query
--    and any future "tasks idle for N seconds" check need a monotonically
--    advancing timestamp. Backfilled from createdAt for existing rows;
--    triggers keep it fresh on every row update.
--
-- 2. autonomy_state \u2014 a key/value table so the AutonomyLoop can persist
--    durable observability state (last_reflection_at, last_suppression_sweep_at,
--    paused_until, paused_reason, etc.) in SQL rather than the JSON checkpoint
--    file. Coexists with the JSON checkpoint for now; the JSON file remains
--    canonical for goals/gap-history, and SQL becomes canonical for
--    observability counters and pause/cooldown state the dashboard reads.
--
-- Schema choice: a narrow key/value (TEXT/TEXT/INTEGER) table over a wide
-- one-row table because (a) the autonomy loop is still adding new state
-- fields and we don't want a migration per field, (b) the dashboard reads
-- a small bounded set of keys, (c) the row count never grows beyond ~30.

-- UP

-- \u2500\u2500 tasks.updated_at \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

ALTER TABLE tasks ADD COLUMN updated_at INTEGER NOT NULL DEFAULT 0;

-- Backfill from createdAt (ISO 8601 \u2192 epoch ms). strftime('%s', x)*1000
-- gives second precision; existing rows don't need sub-second resolution.
UPDATE tasks
SET updated_at = CAST(strftime('%s', createdAt) AS INTEGER) * 1000
WHERE updated_at = 0;

-- Future inserts: default to current time so callers that don't explicitly
-- set updated_at still get a sane value. Trigger updates the value on every
-- UPDATE so callers don't have to remember to bump it.
CREATE TRIGGER IF NOT EXISTS trg_tasks_updated_at_insert
AFTER INSERT ON tasks
WHEN NEW.updated_at = 0
BEGIN
	UPDATE tasks
	SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
	WHERE id = NEW.id;
END;

CREATE TRIGGER IF NOT EXISTS trg_tasks_updated_at_update
AFTER UPDATE ON tasks
FOR EACH ROW
WHEN NEW.updated_at = OLD.updated_at
BEGIN
	UPDATE tasks
	SET updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
	WHERE id = NEW.id;
END;

CREATE INDEX IF NOT EXISTS idx_tasks_status_updated_at
	ON tasks(status, updated_at);

-- \u2500\u2500 autonomy_state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

CREATE TABLE IF NOT EXISTS autonomy_state (
	key         TEXT    NOT NULL PRIMARY KEY,
	value       TEXT,                 -- JSON or scalar, caller decides
	value_num   INTEGER,              -- optional fast-path for numeric reads
	updated_at  INTEGER NOT NULL
);

-- DOWN

DROP TABLE IF EXISTS autonomy_state;
DROP INDEX IF EXISTS idx_tasks_status_updated_at;
DROP TRIGGER IF EXISTS trg_tasks_updated_at_update;
DROP TRIGGER IF EXISTS trg_tasks_updated_at_insert;
-- SQLite cannot drop columns portably in older runtimes; tasks.updated_at
-- is left in place on rollback. Matches the additive-only convention used
-- by migrations 003/004/006/008/010/011.
`;

