// src/tasks/migrations/023_kernel_events.sql
var kernel_events_default = "-- Migration 023: kernel_events append-only journal.\n-- Single source of truth for the autonomy kernel: every trust-affecting\n-- event (task outcomes, demotions, promotions) lands here as a row.\n-- Append-only is enforced at the DB layer via BEFORE UPDATE / BEFORE DELETE\n-- triggers so no caller can rewrite history.\n\n-- UP\n\nCREATE TABLE IF NOT EXISTS kernel_events (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts INTEGER NOT NULL,\n  kind TEXT NOT NULL,\n  lane TEXT,\n  ref TEXT,\n  weight REAL NOT NULL,\n  payload TEXT NOT NULL,\n  created_at INTEGER NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_kernel_events_kind_ts ON kernel_events(kind, ts);\n\nCREATE INDEX IF NOT EXISTS idx_kernel_events_lane_ts ON kernel_events(lane, ts);\n\nCREATE TRIGGER IF NOT EXISTS kernel_events_no_update\nBEFORE UPDATE ON kernel_events\nBEGIN\n  SELECT RAISE(ABORT, 'kernel_events is append-only');\nEND;\n\nCREATE TRIGGER IF NOT EXISTS kernel_events_no_delete\nBEFORE DELETE ON kernel_events\nBEGIN\n  SELECT RAISE(ABORT, 'kernel_events is append-only');\nEND;\n\n-- DOWN\n\nDROP TRIGGER IF EXISTS kernel_events_no_update;\nDROP TRIGGER IF EXISTS kernel_events_no_delete;\nDROP INDEX IF EXISTS idx_kernel_events_kind_ts;\nDROP INDEX IF EXISTS idx_kernel_events_lane_ts;\nDROP TABLE IF EXISTS kernel_events;\n";

// src/tasks/migrations/024_goal_records.sql
